-- -----------------------------------
-- Table structure for `daily_downsite_table_test`
-- -----------------------------------

DROP TABLE IF EXISTS `daily_downsite_table_test`;
CREATE TABLE `daily_downsite_table_test` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `ATMID` varchar(100) CHARACTER SET utf8mb4 NOT NULL,
  `last_communication` date NOT NULL,
  `SN` int(11) NOT NULL,
  `today_date` date NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=59 DEFAULT CHARSET=latin1;

